package com.bank.spark.model;

import java.util.HashSet;
import java.util.Set;

// Columns referenced by each part of a query.
public class QueryColumns {
    private final Set<String> finalProjection = new HashSet<>();
    private final Set<String> filterColumns = new HashSet<>();
    private final Set<String> joinKeys = new HashSet<>();
    private final Set<String> groupByColumns = new HashSet<>();

    public QueryColumns project(String... cols) { finalProjection.addAll(Set.of(cols)); return this; }
    public QueryColumns filter(String... cols) { filterColumns.addAll(Set.of(cols)); return this; }
    public QueryColumns join(String... cols) { joinKeys.addAll(Set.of(cols)); return this; }
    public QueryColumns groupBy(String... cols) { groupByColumns.addAll(Set.of(cols)); return this; }

    public Set<String> getFinalProjection() { return finalProjection; }
    public Set<String> getFilterColumns() { return filterColumns; }
    public Set<String> getJoinKeys() { return joinKeys; }
    public Set<String> getGroupByColumns() { return groupByColumns; }
}
