package com.bank.spark.service;

import com.bank.spark.model.QueryColumns;

import java.util.TreeSet;

// Computes the minimal column set like Catalyst does — union across the plan.
public class ProjectionPruner {

    // Needed = projection ∪ filters ∪ join keys ∪ group-by columns.
    public TreeSet<String> neededColumns(QueryColumns q) {
        TreeSet<String> needed = new TreeSet<>();
        needed.addAll(q.getFinalProjection());
        needed.addAll(q.getFilterColumns());
        needed.addAll(q.getJoinKeys());
        needed.addAll(q.getGroupByColumns());
        return needed;
    }

    // Fraction of columns (and roughly bytes) actually read.
    public double fractionRead(int neededCount, int totalColumns) {
        return (double) neededCount / totalColumns;
    }
}
