package com.bank.spark;

import com.bank.spark.model.QueryColumns;
import com.bank.spark.service.ProjectionPruner;

import java.util.TreeSet;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ColumnPruningDemo {

    private static final Logger log = Logger.getLogger(ColumnPruningDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ProjectionPruner pruner = new ProjectionPruner();
        int totalColumns = 100; // wide transactions table

        // A query that even "selects 50 columns" early but ultimately uses only a few.
        QueryColumns q = new QueryColumns()
                .project("accountId", "amount", "txnDate")  // final output
                .filter("amount")                            // WHERE amount > 50000
                .join("accountId")                           // join accounts on accountId
                .groupBy("txnDate");                          // group by date

        TreeSet<String> needed = pruner.neededColumns(q);
        log.info(() -> "ReadSchema (pruned): " + needed + "  (" + needed.size() + " of " + totalColumns + " columns)");

        double fraction = pruner.fractionRead(needed.size(), totalColumns);
        log.info(() -> "Projection pushdown reads ~" + Math.round(fraction * 100) + "% of the data");
        log.info(() -> "95 columns skipped on disk — never read because no operator needs them");

        log.info("Even an early select(50 cols) is pruned: Catalyst keeps only what the output/conditions use.");
    }
}

